package com.openggf.game.soniccd;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static com.openggf.game.soniccd.CdIpxProgress.*;
/** Tests FIRST; inactive source-ordered row reads, not command/source/entry authority. */
class TestCdIpxPostWarpDestination {
 static final class Fault extends RuntimeException{}
 static final class Reads implements WarpDestinationReads {
  final List<String> order=new ArrayList<>();final int[] livePeriod;int future;final int[] row={0x61,0x70,0xE1,0xD4};String fail;final Fault fault=new Fault();
  Reads(int raw,int good){livePeriod=new int[]{raw};future=good;}
  void reached(String site){order.add(site);if(site.equals(fail))throw fault;}
  public int rawPeriod(){reached("period");return livePeriod[0];}public int commandByte(WarpCommandRow r){reached(r.name());return row[r.commandByteOffset()];}public int goodFuture(){reached("goodFuture");return future;}
 }
 @Test void all256RawBytesSelectByLocalMaskWithoutChangingTheLiveHighMarker(){for(int raw=0;raw<256;raw++){var p=new Reads(raw,0);var d=postWarpDestination(p);assertEquals(raw,p.livePeriod[0]);assertEquals(raw,d.rawPeriodByte());int v=raw&127;assertEquals(v==0?WarpPeriod.PAST:v==1?WarpPeriod.PRESENT:WarpPeriod.FUTURE,d.period());assertEquals(v==0?WarpCommandRow.PAST:v==1?WarpCommandRow.PRESENT:WarpCommandRow.BAD_FUTURE,d.row());assertEquals(p.row[d.row().commandByteOffset()],d.commandByte());assertEquals(v==0?List.of("period","PAST"):v==1?List.of("period","PAST","PRESENT"):List.of("period","PAST","PRESENT","BAD_FUTURE","goodFuture"),p.order);}}
 @Test void all256GoodFutureBytesUseFullNonzeroByteRatherThanBitZero(){for(int good=0;good<256;good++)for(int raw:new int[]{2,0x82,0xFF}){var p=new Reads(raw,good);var d=postWarpDestination(p);assertEquals(good==0?WarpCommandRow.BAD_FUTURE:WarpCommandRow.GOOD_FUTURE,d.row());assertEquals(good==0?0xD4:0xE1,d.commandByte());assertEquals(good==0?List.of("period","PAST","PRESENT","BAD_FUTURE","goodFuture"):List.of("period","PAST","PRESENT","BAD_FUTURE","goodFuture","GOOD_FUTURE"),p.order);assertEquals(raw,p.livePeriod[0]);assertEquals(good,p.future);}}
 @Test void pastAndPresentNeverReadUnknownGoodFuture(){for(int raw:new int[]{0,1,0x80,0x81}){var p=new Reads(raw,0);p.fail="goodFuture";assertNotNull(postWarpDestination(p));assertFalse(p.order.contains("goodFuture"));}}
 @Test void rawPeriodFaultPrecedesEveryCommandRead(){var p=new Reads(0,0);p.fail="period";assertSame(p.fault,assertThrows(Fault.class,()->postWarpDestination(p)));assertEquals(List.of("period"),p.order);}
 @Test void pastReadIsRequiredEvenWhenFutureWouldEventuallyBeChosen(){var p=new Reads(0x82,1);p.fail="PAST";assertSame(p.fault,assertThrows(Fault.class,()->postWarpDestination(p)));assertEquals(List.of("period","PAST"),p.order);}
 @Test void presentReadPrecedesBadFutureAndGoodFuture(){var p=new Reads(0xFE,1);p.fail="PRESENT";assertSame(p.fault,assertThrows(Fault.class,()->postWarpDestination(p)));assertEquals(List.of("period","PAST","PRESENT"),p.order);}
 @Test void badFutureReadOccursBeforeTheConditionalGoodFutureRead(){var p=new Reads(2,1);p.fail="BAD_FUTURE";assertSame(p.fault,assertThrows(Fault.class,()->postWarpDestination(p)));assertEquals(List.of("period","PAST","PRESENT","BAD_FUTURE"),p.order);}
 @Test void unknownGoodFutureStopsAtItsActualReadWithoutChoosingADefault(){var p=new Reads(0x82,0);p.fail="goodFuture";assertSame(p.fault,assertThrows(Fault.class,()->postWarpDestination(p)));assertEquals(List.of("period","PAST","PRESENT","BAD_FUTURE","goodFuture"),p.order);assertEquals(0x82,p.livePeriod[0]);}
 @Test void goodRowFailureRetainsEveryPriorReadAndOriginalFault(){var p=new Reads(2,0x80);p.fail="GOOD_FUTURE";assertSame(p.fault,assertThrows(Fault.class,()->postWarpDestination(p)));assertEquals(List.of("period","PAST","PRESENT","BAD_FUTURE","goodFuture","GOOD_FUTURE"),p.order);assertEquals(0,p.fault.getSuppressed().length);}
 @Test void allSourceBytesCheckWidthsBeforeTheNextReadRatherThanMaskingInvalidValues(){for(int bad:new int[]{-1,256,65535}){var p=new Reads(bad,0);assertThrows(IllegalArgumentException.class,()->postWarpDestination(p));assertEquals(List.of("period"),p.order);for(var row:WarpCommandRow.values()){var q=new Reads(2,1);q.row[row.commandByteOffset()]=bad;assertThrows(IllegalArgumentException.class,()->postWarpDestination(q));assertEquals(row.name(),q.order.getLast());}var q=new Reads(2,bad);assertThrows(IllegalArgumentException.class,()->postWarpDestination(q));assertEquals("goodFuture",q.order.getLast());}}
 @Test void selectionIsInertAndRejectsContradictoryWidthsRowsAndPeriods(){assertThrows(NullPointerException.class,()->postWarpDestination(null));assertEquals(0,WarpCommandRow.PRESENT.commandByteOffset());assertEquals(1,WarpCommandRow.PAST.commandByteOffset());assertEquals(2,WarpCommandRow.GOOD_FUTURE.commandByteOffset());assertEquals(3,WarpCommandRow.BAD_FUTURE.commandByteOffset());assertThrows(IllegalArgumentException.class,()->new WarpDestination(0,WarpPeriod.FUTURE,WarpCommandRow.BAD_FUTURE,1));assertThrows(IllegalArgumentException.class,()->new WarpDestination(1,WarpPeriod.PRESENT,WarpCommandRow.PAST,1));assertThrows(IllegalArgumentException.class,()->new WarpDestination(2,WarpPeriod.FUTURE,WarpCommandRow.GOOD_FUTURE,256));assertThrows(NullPointerException.class,()->new WarpDestination(2,null,WarpCommandRow.BAD_FUTURE,1));}
}
